    content: {
      introduction: `인플루언서 마케팅은 대기업만의 전략이 아닙니다. 팔로워 1000~10000명의 마이크로 인플루언서와의 협업은 오히려 대형 인플루언서보다 높은 참여율과 전환율을 보이는 경우가 많습니다. 100만 원 이하의 예산으로도 브랜드 인지도를 높이고 실제 판매로 연결할 수 있습니다. 이 가이드에서는 인플루언서 마케팅을 처음 시작하는 분들을 위한 실전 전략을 소개합니다.`,
      sections: [
        {
          heading: '인플루언서 유형별 특징과 예산 기준',
          content: `인플루언서는 팔로워 수에 따라 크게 4가지로 분류됩니다. 예산과 목표에 맞는 유형 선택이 중요합니다.

**나노 인플루언서 (1000~10000명):**
- 참여율: 5~10% (가장 높음)
- 협업 비용: 무료~10만 원 (제품 협찬만으로 협업 가능)
- 특징: 특정 니치 커뮤니티에 강한 영향력, 팔로워와의 신뢰 깊음

**마이크로 인플루언서 (10000~100000명):**
- 참여율: 2~5%
- 협업 비용: 10~100만 원
- 특징: 특정 분야 전문성, 팬층의 충성도 높음

**매크로 인플루언서 (100000~1000000명):**
- 참여율: 1~2%
- 협업 비용: 100만~1000만 원
- 특징: 넓은 노출, 브랜드 인지도 상승에 효과적

**메가 인플루언서 (100만+명):**
- 참여율: 0.5~1%
- 협업 비용: 1000만 원 이상
- 특징: 대규모 캠페인에 적합

소규모 브랜드라면 나노~마이크로 인플루언서 여러 명과 협업하는 것이 메가 인플루언서 한 명보다 ROI가 높습니다.`
        },
        {
          heading: '인플루언서 발굴과 적합성 검증',
          content: `좋은 인플루언서를 찾는 것이 성공적인 협업의 80%를 결정합니다.

**인플루언서 발굴 방법:**
1. **인스타그램 해시태그 검색**: 업종 관련 해시태그에서 꾸준히 게시하는 계정 탐색
2. **경쟁사 협업 인플루언서 파악**: 경쟁사 태그 게시물에서 좋은 반응을 받은 협업 계정 확인
3. **크리에이터 플랫폼**: Mediacreator, 블링, 유니크 같은 국내 인플루언서 플랫폼 활용
4. **직접 DM 발굴**: 이미 제품 카테고리에 관심 있어 하는 계정에 직접 접근

**인플루언서 적합성 검증 체크리스트:**
- 가짜 팔로워 여부: 팔로워 대비 좋아요/댓글 수 확인 (1만 팔로워에 좋아요 10개는 이상)
- 콘텐츠 품질: 최근 12개 게시물의 일관성과 완성도 확인
- 팔로워 인구통계: 타겟 고객과 일치하는지 확인
- 브랜드 안전성: 과거 게시물에 논란이 될 내용이 없는지 검토
- 이전 협업 게시물의 반응: 협찬 게시물에도 팔로워가 자연스럽게 반응하는지 확인`
        },
        {
          heading: '협업 제안과 계약 시 주의사항',
          content: `인플루언서에게 처음 연락할 때부터 계약까지 놓치면 안 되는 포인트를 알아봅니다.

**효과적인 협업 제안 DM 구성:**
1. 본인과 브랜드 소개 (2~3줄)
2. 왜 이 인플루언서를 선택했는지 구체적 언급 (최근 포스트 언급 등)
3. 협업 내용 요약 (어떤 제품, 어떤 형식, 언제)
4. 보상 조건 명시 (제품 + 현금, 또는 협의)
5. 다음 단계 안내 (이메일 또는 추가 DM으로 세부 논의)

**계약서 필수 포함 항목:**
- 게시 플랫폼과 콘텐츠 형식 (릴스, 피드 포스트, 스토리 등)
- 게시 날짜와 시간
- 필수 포함 사항 (브랜드 태그, 해시태그, 공식 계정 언급)
- 게시 유지 기간 (최소 30일 권장)
- 협찬 표시 의무 (#광고, #협찬)
- 저작권 (인플루언서 제작 콘텐츠를 브랜드가 재사용할 수 있는지)
- 보상 지급 방법과 시기`
        },
        {
          heading: '협업 성과 측정과 ROI 계산',
          content: `인플루언서 마케팅 효과를 정확히 측정하면 다음 캠페인을 더 효율적으로 기획할 수 있습니다.

**주요 성과 지표(KPI):**
- **도달 수**: 게시물을 본 총 계정 수
- **참여율**: (좋아요+댓글+공유) / 팔로워 수
- **저장 수**: 나중에 참고할 의도가 있는 독자 수
- **링크 클릭 수**: 프로필 링크 클릭, 스토리 링크 클릭
- **전환 수**: 실제 구매, 회원가입, 쿠폰 사용

**추적 방법:**
- 인플루언서별 UTM 파라미터 링크 제공
- 인플루언서 전용 할인 코드 발급 (예: JISU10 → 10% 할인)
- 랜딩 페이지 별도 제작

**ROI 계산 공식:**
ROI = (협업으로 발생한 매출 - 협업 비용) / 협업 비용 × 100%

인플루언서 마케팅 초기에는 직접적인 매출 외에 브랜드 인지도, 팔로워 증가, UGC 확보 같은 간접 가치도 함께 평가하세요.`
        }
      ],
      conclusion: `인플루언서 마케팅은 처음 한두 번의 협업에서 완벽한 결과를 기대하기 어렵습니다. 소규모 협업을 여러 번 진행하면서 어떤 유형의 인플루언서가, 어떤 콘텐츠 형식이 우리 브랜드에 맞는지 데이터를 쌓아가는 과정입니다. 오늘 당장 인스타그램에서 브랜드와 연관된 해시태그를 검색하고 나노 인플루언서 5명의 계정을 후보 리스트에 올려보세요.`
    },
    relatedTools: ['hashtag-mixer', 'qr-generator'],
