      { question: '모바일과 데스크톱 SEO 점수가 크게 다를 때 어느 것을 우선해야 하나요?', answer: '모바일 점수를 우선하세요. 구글은 모바일 버전 기준으로 색인하고 순위를 매깁니다. 데스크톱 점수가 높아도 모바일 점수가 낮으면 검색 순위에 부정적 영향을 줍니다.' },
      { question: '반응형 디자인과 모바일 별도 사이트 중 무엇이 더 SEO에 좋나요?', answer: '구글은 반응형 웹을 가장 권장합니다. 단일 URL로 모든 기기에 서비스하므로 백링크가 분산되지 않고 관리가 쉽습니다. m. 도메인의 별도 모바일 사이트는 canonical 설정이 까다롭고 관리 비용이 2배입니다.' },
      { question: '앱이 있으면 모바일 웹 SEO를 신경 쓰지 않아도 되나요?', answer: '앱과 모바일 웹은 별개입니다. 앱은 앱스토어 검색에 특화되고, 모바일 웹은 구글/네이버 검색을 통한 신규 발굴에 중요합니다. 기존 사용자에게는 앱, 신규 발굴은 모바일 웹의 역할로 서로 보완 관계입니다.' },
      { question: '모바일 SEO에서 가장 빠른 효과를 내는 개선 항목은?', answer: '이미지 최적화(WebP 전환, lazy loading, 크기 명시)가 가장 빠른 효과를 줍니다. 대부분의 사이트에서 이미지 최적화만으로 LCP가 1~2초 개선됩니다. 그 다음은 렌더링 블로킹 JS/CSS 제거입니다.' }
