    description: '구글 AI 오버뷰(SGE)가 블로그 트래픽에 미치는 영향과 대응 전략. AEO 최적화, EEAT 강화, 직접 트래픽 전환으로 AI 검색 시대에도 성장하는 방법을 안내합니다.',
