      conclusion: `Figma는 처음엔 낯설지만, 1~2시간만 투자하면 기본 소셜 카드를 혼자 만들 수 있습니다. 디자이너에게 매번 요청하는 대신 직접 시안을 만들어 빠른 피드백을 받으면 캠페인 속도가 달라집니다. 커뮤니티 템플릿 → 텍스트/색상 교체 → Export 이 흐름부터 익히고, 크레피카의 글자수 카운터로 텍스트 분량을 최적화하세요.`
