    relatedTools: ['webp-converter'],
    relatedPosts: ['aeo-search-future-guide', 'geo-optimization-strategy'],
    faq: [
      { question: 'PageSpeed Insights 점수가 모바일과 데스크톱에서 크게 차이나는 이유는?', answer: '모바일 시뮬레이션은 느린 네트워크(4G)와 중급 사양 기기를 기준으로 하기 때문에 데스크톱보다 훨씬 낮게 나옵니다. 모바일 점수 60점이면 실제 사용자 경험은 나쁘지 않을 수 있습니다. 중요한 것은 점수보다 실제 필드 데이터(CrUX)입니다.' },
      { question: 'CLS 점수를 올리는 가장 쉬운 방법은?', answer: '모든 이미지와 동영상에 width와 height 속성을 지정하는 것이 가장 빠른 방법입니다. 또한 광고, 임베드 콘텐츠에 고정 크기의 컨테이너를 지정하면 로딩 중 레이아웃 이동을 막을 수 있습니다.' },
      { question: 'Lighthouse 점수와 실제 사용자 경험은 얼마나 일치하나요?', answer: 'Lighthouse는 시뮬레이션 환경이고, Search Console의 CrUX 데이터는 실제 사용자 경험입니다. 둘 사이에 차이가 있을 수 있습니다. SEO 랭킹에는 Lighthouse보다 CrUX 기반의 실제 데이터가 사용됩니다.' },
      { question: '속도 최적화 후 순위에 반영되는 데 얼마나 걸리나요?', answer: '구글이 개선된 Core Web Vitals를 인지하고 랭킹에 반영하는 데 수 주에서 수 개월이 소요됩니다. 또한 속도는 랭킹 신호 중 하나일 뿐이므로 다른 SEO 요소도 함께 강화해야 효과가 나타납니다.' },
      { question: 'Vite로 빌드한 SPA에서 LCP를 최적화하는 방법은?', answer: 'SPA는 초기 HTML이 비어있어 LCP가 낮게 나올 수 있습니다. 히어로 이미지에 preload 추가, 서버 사이드 렌더링(SSR) 또는 정적 생성(SSG) 도입, 중요 콘텐츠의 초기 HTML 포함(SSR/prerender) 등이 효과적입니다.' }
    ]
