    faq: [
      { question: 'Buffer 무료 플랜으로 시작하면 충분한가요?', answer: '채널 3개, 월 30게시물(채널당 10개) 한도라면 초기에는 충분합니다. Instagram, X, LinkedIn을 각각 채널로 등록하고 Meta Business Suite로 Facebook+Instagram을 추가 관리하면 무료로 주요 플랫폼을 모두 커버할 수 있습니다.' },
      { question: '예약 발행 도구를 사용하면 알고리즘에 불이익이 있나요?', answer: '공식 파트너 앱(Meta Business Suite, TikTok Creator Tools)을 제외한 서드파티 도구는 과거에 알고리즘 불이익이 있었지만, 현재는 대부분의 주요 플랫폼이 공식 API를 제공해 불이익이 거의 없어졌습니다. Buffer, Later 등은 모두 공식 API를 사용합니다.' },
      { question: '인스타그램 스토리도 예약 발행이 가능한가요?', answer: 'Buffer, Later, Hootsuite 등에서 스토리 예약 발행이 가능합니다. 단, 스토리 인터랙티브 요소(투표, 질문 스티커 등)는 서드파티에서 지원하지 않는 경우가 있어, 발행 후 수동으로 추가해야 할 수 있습니다.' },
      { question: 'TikTok 예약 발행도 지원하는 도구가 있나요?', answer: 'Buffer, Later, Publer 등이 TikTok 예약 발행을 지원합니다. TikTok 자체적으로도 TikTok Creator Studio에서 예약 발행 기능을 제공합니다. 하지만 TikTok의 짧은 트렌드 사이클을 고려하면 실시간 발행 비중을 높게 유지하는 것이 좋습니다.' },
      { question: '여러 소셜미디어 계정을 관리하는 대행사에게 추천하는 도구는?', answer: 'Sprout Social($249+/월), Hootsuite($99+/월), Sendible($29+/월)을 추천합니다. 팀 협업, 승인 워크플로우, 고객사 계정 분리 관리 기능이 핵심입니다. 고객사 수와 규모에 맞는 플랜을 선택하세요.' }
    ]
