        {
          title: '월 10만원 예산으로 구글 광고 운영하기',
          content: `소액 예산에서도 효과를 낼 수 있는 운영 전략입니다.

**예산 분배:**
- 일 예산 = 월 예산 ÷ 30. 월 10만원 → 일 3,300원
- 처음에는 단일 캠페인 집중: 예산을 분산하면 각 캠페인이 통계를 쌓기 어려움
- 학습 기간 (2~4주): 최소 20~30번의 클릭이 있어야 의미 있는 데이터 수집

**소액 예산 운영 주의사항:**
- 자동 입찰보다 수동 CPC 입찰: 처음에는 CPC를 직접 통제
- 높은 품질 점수 유지: 랜딩 페이지 내용과 키워드의 관련성을 높이면 CPC 절감 효과
- 시간대·지역 조정: 성과가 좋은 시간대와 지역에 예산 집중 (운영 2~4주 후 데이터 기반)
- 검색어 보고서 주 1회 확인: 예상치 못한 키워드에 광고 노출 시 부정 키워드에 추가

**성과 추적:**
구글 애널리틱스 4와 Google Ads를 연동해 광고 클릭 후 행동을 추적하세요. 전환 추적 없이는 어떤 키워드가 실제 성과로 이어지는지 알 수 없습니다.`
        }
