    description: '콘텐츠 마케팅의 투자 대비 효과를 측정하는 방법을 단계별로 설명합니다. GA4, 전환 추적, 귀속 모델을 활용해 콘텐츠의 비즈니스 가치를 수치화하는 법을 안내합니다.',
