    faq: [
      { question: '카드뉴스와 인포그래픽의 차이는 무엇인가요?', answer: '카드뉴스는 여러 장의 카드로 정보를 순서대로 전달하는 형식으로 SNS에 최적화됩니다. 인포그래픽은 한 장의 이미지에 데이터와 정보를 시각화한 형식입니다. 카드뉴스는 스토리텔링에, 인포그래픽은 통계와 데이터 시각화에 더 적합합니다.' },
      { question: '카드뉴스 몇 장이 적당한가요?', answer: '인스타그램 캐러셀은 최대 10장이고, 5~8장이 일반적으로 완독률이 높습니다. 3장 이하는 너무 짧아 정보가 부족해 보이고, 10장 이상은 이탈률이 높아집니다. 내용에 맞게 조절하되 불필요한 카드는 과감히 제거하세요.' },
      { question: '카드뉴스 폰트는 어떤 것이 좋나요?', answer: '한글 카드뉴스에는 Pretendard, Noto Sans KR, 나눔스퀘어를 추천합니다. 무료로 사용 가능하고 가독성이 좋습니다. 제목에는 Bold~ExtraBold 굵기, 본문에는 Regular~Medium 굵기를 사용하고, 같은 시리즈에서는 동일한 폰트를 유지하세요.' },
      { question: '카드뉴스를 블로그에서도 활용할 수 있나요?', answer: '네, 블로그 포스트 중간에 카드뉴스 이미지를 삽입하면 긴 텍스트의 가독성이 높아집니다. 특히 "핵심 요약" 카드를 블로그 중간에 배치하면 방문자의 체류 시간이 늘어나 SEO에도 유리합니다.' },
      { question: '카드뉴스 제작 비용을 줄이는 방법은?', answer: '처음에는 Canva 무료 플랜의 템플릿을 활용하는 것이 가장 경제적입니다. 한 번 만든 템플릿을 복사해서 내용만 바꾸면 일관된 시리즈를 빠르게 만들 수 있습니다. 폰트, 색상, 레이아웃을 고정한 브랜드 템플릿을 만들어 두면 제작 시간이 대폭 줄어듭니다.' }
    ]
