      conclusion: '썸네일 CTR을 높이는 핵심은 짧은 텍스트, 강한 색 대비, 얼굴 이미지, 그리고 궁금증을 자극하는 구성입니다. 크레피카 도구로 제목을 다듬고, 색 팔레트를 정하면 썸네일 제작 시간도 절반으로 줄어듭니다.'
