    faq: [
      { question: '유튜브 썸네일 최적 크기는 얼마인가요?', answer: '유튜브 권장 썸네일 크기는 1280x720px(16:9 비율)이며, 최소 640x360px 이상이어야 합니다. 파일 크기는 2MB 이하, JPG 또는 PNG 형식을 지원합니다. 텍스트는 중앙에서 약 10% 안쪽 안전 영역에 배치하면 잘리지 않습니다.' },
      { question: '썸네일 제작에 무료 도구가 있나요?', answer: '네, Canva 무료 플랜이 가장 접근하기 쉽습니다. 유튜브 썸네일 템플릿이 수천 개 제공되며, 텍스트와 이미지를 간단히 교체해서 쓸 수 있습니다. Adobe Express(구 Spark)도 무료 플랜에서 충분한 기능을 제공합니다.' },
      { question: '썸네일에 텍스트를 넣지 않아도 되나요?', answer: '플랫폼과 채널 특성에 따라 다릅니다. 여행·음식·패션 계정은 텍스트 없이 고화질 이미지만으로도 클릭률이 높습니다. 반면 정보 전달형 채널(강의, 리뷰, 뉴스)은 텍스트가 있어야 콘텐츠를 미리 파악할 수 있어 CTR이 올라갑니다. 자신의 콘텐츠 성격에 맞게 선택하세요.' },
      { question: 'CTR은 얼마나 되어야 좋은가요?', answer: '유튜브 기준으로 CTR 4~6%면 평균, 6~10%면 양호, 10% 이상이면 우수로 봅니다. 단, 채널 규모와 주제에 따라 기준이 다르므로 내 채널 과거 평균 대비 상승 추세를 보는 것이 더 중요합니다.' },
      { question: '썸네일 클릭률을 높였는데 시청 지속률이 낮아졌어요. 왜 그런가요?', answer: '썸네일과 콘텐츠 내용이 불일치할 때 나타나는 현상입니다. 자극적인 썸네일이 클릭을 유도하지만, 기대에 못 미치는 내용이면 바로 이탈합니다. 썸네일은 콘텐츠의 핵심을 정확히 표현해야 CTR과 시청 지속률이 함께 올라갑니다.' }
    ]
