    description: '인스타그램, 유튜브, 블로그, 뉴스레터에서 바로 쓸 수 있는 CTA(Call to Action) 문구 50가지. 팔로우, 구독, 댓글, 공유, 구매 유도별로 분류해 정리했습니다.',
